  XX(13) = XX(13)-JVS(1604)*XX(343)-JVS(3577)*XX(439)
  XX(12) = XX(12)-JVS(1657)*XX(349)-JVS(3576)*XX(439)
  XX(11) = XX(11)-JVS(1673)*XX(351)-JVS(3575)*XX(439)
  XX(10) = XX(10)-JVS(2151)*XX(384)-JVS(3574)*XX(439)
  XX(9) = XX(9)-JVS(2215)*XX(390)-JVS(3573)*XX(439)
  XX(8) = XX(8)-JVS(2251)*XX(394)-JVS(3572)*XX(439)
  XX(7) = XX(7)-JVS(2393)*XX(406)-JVS(3571)*XX(439)
  XX(6) = XX(6)-JVS(3156)*XX(435)-JVS(3570)*XX(439)
  XX(5) = XX(5)-JVS(3569)*XX(439)-JVS(4365)*XX(442)
  XX(4) = XX(4)-JVS(2734)*XX(423)-JVS(3568)*XX(439)
  XX(3) = XX(3)
  XX(2) = XX(2)
  XX(1) = XX(1)
      
END SUBROUTINE KppSolveTR

! End of KppSolveTR function
